import {
    Table,
    BooleanColumn,
    ReferenceColumn,
    UserRolesColumn,
    IntegerColumn,
    ListColumn,
    StringColumn,
    TranslatedFieldColumn,
    GuidColumn,
} from '@servicenow/sdk/core'

export const pa_dashboards = Table({
    allowWebServiceAccess: true,
    attributes: {
        text_index_translations: true,
        update_synch: true,
    },
    extends: 'analytics_dashboard',
    label: 'Dashboard',
    name: 'pa_dashboards',
    schema: {
        no_tabs: BooleanColumn({
            default: false,
            label: 'No tabs',
        }),
        group: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Group',
            referenceTable: 'pa_dashboards_group',
        }),
        is_breakdown: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'A breakdown dashboard can be used to set the widgets on the dashboard in the context of a specified breakdown. For example see all scores around New, Open & Closed Incidents, Problems and Changes from the perspective of a specific assignment group.',
                    label: 'Breakdown Source dashboard',
                    plural: 'Breakdown Source dashboards',
                    language: 'en',
                    url: 'http://docs.servicenow.com/?context=Creating_Dashboards_Breakdown_Dashboards',
                    urlTarget: '_blank',
                },
            ],
        }),
        breakdown_source: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Breakdown source',
            referenceTable: 'pa_dimensions',
        }),
        managed_breakdown: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Managed breakdown',
            referenceTable: 'pa_breakdowns',
            referenceQual: 'javascript:new PAUtils().ref_qual_managed_breakdown()',
        }),
        managed_publisher: ReferenceColumn({
            label: 'Act as filter',
            referenceTable: 'sys_ui_hp_publisher',
        }),
        role_override: BooleanColumn({
            default: true,
            label: 'Visible by all roles',
        }),
        roles: UserRolesColumn({
            array: true,
            attributes: {
                no_truncate: true,
            },
            label: 'Requires Roles',
        }),
        disable_multiple_element: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'When selected, you can filter the breakdown dashboard on only one breakdown element at a time. When cleared, you can filter the dashboard on multiple breakdown elements.',
                    label: 'Disable multiple element selection',
                    plural: 'Disable multiple element selections',
                    language: 'en',
                },
            ],
        }),
        visible_to: IntegerColumn({
            default: '2',
            dropdown: 'dropdown_without_none',
            label: 'Visible to',
        }),
        groups: ListColumn({
            attributes: {
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            label: 'Groups',
            maxLength: 1024,
            referenceTable: 'sys_user_group',
        }),
        users: ListColumn({
            attributes: {
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            label: 'Users',
            maxLength: 1024,
            referenceTable: 'sys_user',
        }),
        owner: ReferenceColumn({
            default: 'javascript:gs.getUserID();',
            label: 'Owner',
            mandatory: true,
            referenceTable: 'sys_user',
        }),
        restrict_to_roles: UserRolesColumn({
            array: true,
        }),
        should_migrate_permissions: BooleanColumn({
            default: false,
            label: 'Should migrate permissions',
        }),
        color: StringColumn({
            label: [
                {
                    hint: 'Dashboard Background Color',
                    label: 'Color',
                    plural: 'Colors',
                    language: 'en',
                },
            ],
            maxLength: 7,
        }),
        notification_text: TranslatedFieldColumn({
            label: [
                {
                    hint: 'Displays a notification on the dashboard with an optional link',
                    label: 'Notification Text',
                    plural: 'Notification Texts',
                    language: 'en',
                },
            ],
            maxLength: 200,
        }),
        notification_link_url: StringColumn({
            label: [
                {
                    hint: "The link's URL for the dashboard notification. Must be used with Notification Text",
                    label: 'Notification Link URL',
                    plural: 'Notification Link URLs',
                    language: 'en',
                },
            ],
            maxLength: 256,
        }),
        notification_link_label: TranslatedFieldColumn({
            label: [
                {
                    hint: "The link's text for the dashboard notification. Must be used with Notification Text",
                    label: 'Notification Link Label',
                    plural: 'Notification Link Labels',
                    language: 'en',
                },
            ],
            maxLength: 50,
        }),
        experience_dashboard: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Experience dashboard',
            readOnly: true,
            readOnlyOption: 'instance_configured',
            referenceTable: 'par_dashboard',
        }),
        order: IntegerColumn({
            label: 'Order',
        }),
        no_bulk_migration: BooleanColumn({
            default: false,
            label: 'Do not migrate in bulk',
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
    },
})
